head.b:skin:
/* <Variable name="page.background" description="Page background" type="color" default="#09120e" value="#09120e"/><Variable name="page.text" description="Text color" type="color" default="#e3efe7" value="#e3efe7"/><Variable name="theme.accent" description="Accent color" type="color" default="#83f29a" value="#83f29a"/> */
/* Blogger stylesheet compatibility: restore the spacing Blogger's own widget stylesheet removes, and keep post content inside a phone screen. */
h1{margin:.67em 0}h2{margin:.83em 0}h3{margin:1em 0}h4{margin:1.33em 0}h1,h2,h3,h4,a img{position:static}body{padding:0;word-break:normal}.post-body{width:auto;overflow-x:auto}.post-body a[style*='margin-left'],.post-body a[style*='margin-right']{margin-inline:0!important}.post-body .separator,.post-body .tr-caption-container{max-width:100%}.widget .post-body ul,.widget .post-body ol{margin:1em 0;padding:0 0 0 1.4em;line-height:inherit}.widget .post-body li{margin:0 0 .35em;padding:0}.latest-empty{display:none}.single-view{font-size:1rem}.single-view .post-title{overflow-wrap:anywhere}
:root{--bg:$(page.background);--ink:$(page.text);--accent:$(theme.accent);--heading:"Space Mono",monospace;--body:"Space Mono",monospace}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:16px/1.6 var(--body)}h1,h2,h3{font-family:var(--heading);line-height:1.15}a{color:inherit;text-underline-offset:4px}a:hover{text-decoration-thickness:2px}img{max-width:100%;height:auto}svg{max-width:100%;height:auto}button,input{font:inherit}a:focus-visible,button:focus-visible,summary:focus-visible,input:focus-visible{outline:3px solid currentColor;outline-offset:5px}a,button,summary{touch-action:manipulation}nav{max-width:100%}p,h1,h2,h3,a{overflow-wrap:anywhere}.skip-link{position:fixed;top:-100px;left:16px;z-index:100;background:var(--ink);color:var(--bg);padding:12px}.skip-link:focus{top:12px}.section,.widget{min-width:0;margin:0;padding:0;line-height:inherit}.latest{max-width:1200px;margin:64px auto;padding:0 24px}.posts-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:28px}.post-card{min-width:0}.post-title a{text-decoration:none}.post-title a:hover{text-decoration:underline}.post-media{display:block;aspect-ratio:16/10;overflow:hidden;background:color-mix(in srgb,var(--accent) 12%,var(--bg))}.post-media img{width:100%;height:100%;object-fit:cover}.post-art{height:100%;display:grid;place-items:center;font:italic 70px var(--heading);color:var(--accent)}.post-meta{margin-top:18px;font-size:12px}.post-meta a{margin-right:12px}.pager{display:flex;justify-content:space-between;gap:20px;margin-top:40px;padding-top:20px;border-top:1px solid currentColor}.pager a{padding:10px 0}.post-body{max-width:70ch;margin-inline:auto;overflow-wrap:anywhere}.post-body img,.post-body iframe{max-width:100%}.post-body pre,.post-body table{display:block;overflow:auto;max-width:100%}.single-view .latest{max-width:900px}.single-view .section-heading{display:none}.single-view .post-title{font-size:clamp(32px,5vw,62px)}.single-view #comments{margin-top:60px}.empty-state,.error-state{padding:45px 0}.error-state{max-width:900px;margin:auto;padding:70px 24px}.listing-heading{font-size:clamp(28px,5vw,52px)}#Attribution1,.widget.Attribution{display:none!important}@media(max-width:700px){.posts-grid{grid-template-columns:1fr}.latest{margin:45px auto}.pager{flex-wrap:wrap}}
html{scroll-behavior:smooth}body{margin:0}a{color:inherit}a:focus-visible,button:focus-visible,summary:focus-visible{outline:3px solid var(--accent);outline-offset:5px}img{max-width:100%}header,footer{position:relative}nav{display:flex;gap:24px;flex-wrap:wrap}nav a{text-decoration:none}.wordmark{text-decoration:none;font-weight:700}.brandline{display:flex;align-items:center;justify-content:space-between;gap:24px}.eyebrow{font-size:12px;letter-spacing:.16em;text-transform:uppercase}.art{display:block;width:100%;height:auto}p{line-height:1.7}.post-title a{text-decoration:none}.post-meta{font-size:11px;letter-spacing:.07em;text-transform:uppercase}.post-excerpt{line-height:1.6}.post-media{display:block;width:100%;aspect-ratio:16/10;object-fit:cover}.section-heading{font-size:30px;margin:0 0 30px}.post-title{font-size:24px;line-height:1.2}.post-card{min-width:0}footer{margin-top:80px}footer p{margin:0}.footerline{display:flex;justify-content:space-between;gap:25px;align-items:center}.page-content,.post-body{max-width:760px;margin:auto}.post-body{line-height:1.8}main>.section-heading,main>.posts-grid{max-width:1200px;margin-left:auto;margin-right:auto}#Attribution1,.widget.Attribution{display:none!important}@media(max-width:700px){.brandline,.footerline{align-items:flex-start;flex-direction:column}nav{gap:16px}.section-heading{font-size:26px}.post-title{font-size:22px}main>.section-heading,main>.posts-grid{margin-left:20px;margin-right:20px}}body{font:14px/1.6 "Space Mono",monospace;background:#09120e;color:#e3efe7}header,footer{padding:26px 5vw;border-bottom:1px solid #2c4435}.wordmark{font-size:22px}.prompt,em{color:#83f29a;font-style:normal}nav{font-size:12px}.terminal-hero{margin:40px 5vw 0;border:1px solid #496a54;background:linear-gradient(180deg,#102017,#0a130e)}.terminal-top,.terminal-bottom{padding:12px 20px;display:flex;justify-content:space-between;gap:20px;flex-wrap:wrap;font-size:10px;letter-spacing:.1em;color:#a5b8ac;background:#13271a}.terminal-top{border-bottom:1px solid #496a54}.terminal-bottom{border-top:1px solid #496a54}.terminal-split{display:grid;grid-template-columns:1.05fr 1fr;align-items:center;padding:50px 35px;gap:10px}h1{font-size:clamp(40px,5.8vw,80px);letter-spacing:-.065em;line-height:1.08;margin:25px 0}h1+p{max-width:470px;color:#b2c4b8}.terminal-button{display:inline-flex;gap:45px;margin-top:15px;padding:14px 18px;background:#83f29a;color:#09120e;font-size:12px;text-decoration:none;font-weight:bold}.terminal-button span{transition:transform .2s}.terminal-button:hover span{transform:translate(3px,-3px)}.protocols{padding:70px 5vw}.protocol-grid{display:grid;grid-template-columns:repeat(3,1fr);border:1px solid #344d3d}.protocol-grid article{padding:30px;border-right:1px solid #344d3d}.protocol-grid article:last-child{border:0}.protocol-grid h2{font-size:19px;line-height:1.5}.protocol-grid article>span{color:#83f29a}.protocol-grid p{color:#a5b8ac;font-size:12px}.protocol-grid a{font-size:12px;text-underline-offset:5px}.latest-marker{margin:0 5vw 30px;display:flex;justify-content:space-between;border-top:1px solid #496a54;padding-top:16px;font-size:12px;color:#83f29a}.posts-grid{display:grid;grid-template-columns:1fr;gap:0;margin:0 5vw}.post-card{display:grid;grid-template-columns:140px 1fr;column-gap:30px;padding:28px 0;border-bottom:1px solid #344d3d}.post-media{grid-row:span 5;height:110px;filter:grayscale(1);background:#1e3a29}.post-meta{color:#83f29a}.post-title{font:700 22px/1.5 "Space Mono",monospace;margin:8px 0}.post-excerpt{color:#a5b8ac;margin:0;font-size:12px}.section-heading{margin:0 5vw 15px;font-size:24px}.reference{display:grid;grid-template-columns:1fr 1fr;gap:50px;margin:90px 5vw;padding:40px;background:#12241a;border-left:3px solid #83f29a}.reference h2{font-size:28px;line-height:1.4}.reference details{border-bottom:1px solid #496a54;padding:17px 0}.reference summary{cursor:pointer}.reference details p{font-size:12px;color:#b2c4b8}footer{border-top:1px solid #496a54;font-size:11px;color:#a5b8ac}@media(max-width:700px){.terminal-split,.protocol-grid,.reference{grid-template-columns:1fr}.terminal-split{padding:30px 20px}.circuit{margin-top:30px}.protocol-grid article{border-right:0;border-bottom:1px solid #344d3d}.reference{padding:25px;gap:15px}.post-card{grid-template-columns:80px 1fr;gap:15px}.post-title{font-size:17px}.terminal-top span:last-child{display:none}}
.latest{max-width:none;margin:55px 0;padding:0}.latest>.section-heading,.latest>.posts-grid{max-width:none}a:hover span,a:focus-visible span{transition:transform .2s}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*,*::before,*::after{animation:none!important;transition:none!important}}
@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto!important}*,*::before,*::after{animation:none!important;transition:none!important}.post-media img{transform:none!important}}@media print{nav,.skip-link,.pager{display:none!important}body{background:white;color:black}}
